{"command": "cd /workdir && python3 -c "
import json, csv
r=json.load(open('results.json'))
assert set(r)=={'sensor','network','movie_rank','news_rank','both_rank'}
assert len(r['sensor'])==100 and all(x in (0,1) for x in r['sensor'])
assert len(r['network'])==150 and all(x in (0,1) for x in r['network'])
for k,f in [('movie_rank','movie_test.csv'),('news_rank','news_test.csv'),('both_rank','both_test.csv')]:
    rows=list(csv.DictReader(open('data/'+f)))
    from collections import defaultdict
    exp=defaultdict(list)
    for x in rows: exp[x['query_id']].append(x['doc_id'])
    assert set(r[k])==set(exp), k
    for q in exp: assert sorted(r[k][q])==sorted(exp[q]), (k,q)
print('all shape checks OK')
" && head -c 400 results.json"}

